   "syn": "大内库藏武功秘笈《葵花宝典》失窃。东厂主管太监古今福（刘洵 饰）率千户欧阳全（张学友 饰）等，南下调查辞官锦衣卫林镇南，同时收用「五岳盟主」左冷禅（元华 饰）外围策应。华山派大弟子令狐冲（许冠杰 饰）与师妹岳灵珊（叶童 饰）奉师命增援林镇南，无奈两人实力不济，领得林镇南遗嘱后遁走，二人于路先后巧遇顺风堂堂主刘正风（午马 饰）、日月神教长老曲洋（林正英 饰）、华山派风清扬，获传《笑傲江湖》曲谱和独孤九剑。\n\n各路人马为《葵花宝典》纷纷聚于苗人地界，欧阳全与左冷禅争功不下，遂假扮林平之混入华山派一行。令狐冲结识日月神教任盈盈（张敏 饰）与蓝凤凰（袁洁莹 饰），因曲洋之关系得其协助。古今福与岳不群为《葵花宝典》大打出手，令狐冲不忍一班师兄弟受牵连愤而使出独孤九剑，始明了「笑傲江湖」真意。",
