   "syn": "卢大年（钟镇涛 饰）因替即将出国的姐姐代课来到内湾，在姐姐安排下住进小学音乐老师陈素云（江玲 饰）家的二楼。大年担任四年级忠班的班主任。在班上，他一方面要对付调皮捣蛋出了名的「三剑客」，同时也关心着因父母离婚而性格孤僻的学生周兴旺（郑传文 饰）。\n\n陈素云是个文静的姑娘，整日与大年同来同往，互相产生爱慕之情。在内湾，存在着以投毒和电击的方法捕鱼，大年决心根除这种严重破坏大自然生态的捕鱼方法，在内湾小学发起「爱川护鱼」运动，并在内湾地区推广开来。周兴旺的父亲周文（崔福生 饰）经常去电鱼，为此，他受到同学嘲弄而离家出走。大年和素云要去找回孩子，最后他们能结合在一起吗？",
   "bio": "侯孝贤是台湾新电影的重要导演，代表作包括《风柜来的人》《童年往事》《悲情城市》《戏梦人生》《刺客聂隐娘》。他常以远景、长镜头和克制的叙述，在家庭与地方生活中呈现个人经验和历史变化。",
   "st": "这是侯孝贤早期以流行歌手担纲主演的电影之一，与《就是溜溜的她》《风儿踢踏踩》同属他创作前期。影片保留了爱情喜剧的线索，也把相当多的时间交给孩子、河流与乡村生活，适合与他之后的作品对照观看。",
