   "syn": "雨夜，雷伊（约翰·盖兹 John Getz 饰）跟艾比（弗兰西斯·麦克多蒙德 Frances McDormand 饰）在酒店偷情。雷伊是酒吧伙计，而艾比则是酒吧老板玛迪（丹·哈达娅 Dan Hedaya 饰）的妻子。玛迪怀疑妻子出轨，因此雇佣侦探维斯调查。知悉真相的玛迪怒不可遏，潜入雷伊家，企图绑走妻子，却在厮打中受伤。玛迪密会维斯，决定花钱做掉二人。维斯潜入雷伊家翻到了艾比的手枪。回来后，维斯给玛迪看了两人被杀的照片，趁玛迪不备，将其击毙。雷伊发现玛迪尸体，误以为艾比所为，因此毁尸灭迹。晚上，雷伊再次回到酒吧，赫然发现了威斯假造的照片。这时，雷伊和艾比都不知道，死亡的威胁正在步步紧逼……",
   "bio": "乔尔·科恩与伊桑·科恩长期共同编剧、制作电影。《血迷宫》是他们的长片首作，随后创作了《冰血暴》《谋杀绿脚趾》《老无所依》《醉乡民谣》等作品。他们擅长把类型叙事、黑色幽默与人物的判断失误交织在一起。",
   "st": "影片署名由乔尔·科恩执导、伊桑·科恩制片，两人共同编剧。巴里·索南菲尔德的摄影、卡特·伯韦尔的配乐，以及麦克多蒙德的银幕初亮相，都已在这部早期作品中形成鲜明存在。霓虹、室内光线与声响，持续改变着观众掌握的信息。",
