   "syn": "1948年前后，中国某个平常的遍处皆是断垣颓壁的南方小城里，年轻少妇周玉纹（韦伟 饰）与生病的丈夫戴礼言（石羽 饰）过着索然寡味的日子。战争不仅令礼言失去了家产，也使他丧失了生活的信念。而玉纹每日做的，是在早晨出门买菜、给礼言抓药，在城头踱步好大一会后伤神地复回到家中，将药丢于他时与他对话不过三两句，剩下大半时日，是坐在妹妹戴秀（张鸿眉 饰）房间绣花独自喟叹——除了早晨出门徘徊的城墙头，这是她认为的小城唯剩的有生气之地。\n\n章志忱（李纬 饰）的到来打破了死气沉沉的一切。他是礼言昔日好友，却也是玉纹的旧时情人。与礼言死气的阴郁形成对比的是，志忱年轻健康有朝气，这令本是小城异类的戴秀对他暗生情愫，但志忱心中一直没忘玉纹，而他无疑也是玉纹内心的渴望和呼唤。发乎情止于礼，志忱和玉纹之间欲迎还拒、欲拒还迎的心理角逐游戏连番上演时，礼言和戴秀窥见了个中端倪。",
   "bio": "费穆是中国电影导演，代表作包括《天伦》《狼山喋血记》《小城之春》及戏曲电影《生死恨》。他重视影片整体的气氛、人物的心理节奏与空间关系，《小城之春》也是理解中国电影诗化表达的重要作品。",
   "st": "影片以玉纹的画外音组织感受，让她说出的心事与眼前发生的行动并行。故事围绕少数人物与有限空间展开，情绪常通过走动、停顿、叠化和人物之间的距离表达。破败的城墙与宅院，也持续参与着人物关系的变化。",
