   "syn": "于洛先生（雅克·塔蒂 Jacques Tati 饰）从乡下来，到了巴黎的姐姐（阿德里安娜·色万提 Adrienne Servantie 饰）家里小住，对姐姐家中各种现代化设备极其不适应，经常被搞得手忙脚乱。还好小侄子杰拉德喜欢这个舅舅，和他到处去玩，杰拉德同样不喜欢家里的现代化设备，因此于洛还带他去郊区老屋玩耍。于洛的姐夫阿尔贝勒先生（让·皮埃尔·佐拉 Jean-Pierre Zola 饰）帮于洛在自己工厂找了一份工作，可是于洛同样不适应现代化的操作机器，搞砸了许多事情，闹了许多笑话，姐夫对他忍无可忍，决定介绍另一份工作打发他离开，而于洛开心地同小侄子话别，只当结束了一个不同寻常的假期……",
   "bio": "雅克·塔蒂是法国导演、演员与喜剧创作者，以于洛先生这一银幕形象闻名。代表作包括《于洛先生的假期》《我的舅舅》《玩乐时间》。他的喜剧依靠身体动作、空间调度与声音，把日常环境变成需要耐心观察的舞台。",
   "st": "这是塔蒂的第一部彩色长片，也是第二部于洛先生电影。影片让现代住宅、工厂与老城区形成对照，声音设计和画面构图承担了大量笑料。观看时不必只盯住主角，画面深处或旁边的人物，也可能正在完成一场小小的喜剧。",
