   "syn": "退休多年的顶级杀手约翰·威克刚刚失去妻子，亡妻生前留给他一只小狗，陪他熬过最难的日子。俄罗斯黑帮老大的儿子看中了他的跑车，带人闯进家中抢车、打伤他，还杀死了那只小狗。\n\n曾经让整个地下世界闻风丧胆的约翰重新拿起枪。为了一只狗、一个承诺，他一路杀进黑帮的夜总会、教堂与码头，而那个专为杀手提供庇护的大陆酒店，也第一次向观众打开了大门。",
   "bio": "查德·斯塔赫斯基出身武术与特技行业，曾是基努·里维斯在《黑客帝国》中的替身演员，后与大卫·雷奇创办动作设计公司 87eleven。《疾速追杀》是他的导演首作，此后他执导了该系列全部四部正传，并持续以长镜头、实打实的近身格斗和枪械动作设计影响好莱坞动作片。",
   "st": "影片由特技团队出身的主创打造，动作场面大量采用长镜头和中景拍摄，让观众看清每一次近身格斗与换弹，被称为「枪斗术」。剧本由德瑞克·科尔斯塔德创作，以极简的复仇故事为骨架，搭起了一个有自己规矩、货币与酒店的杀手世界。本片此前从未在中国内地院线上映，这次是系列开山之作首次登上内地大银幕。",
