   "syn": "阿尔穆特是一位前花样滑冰运动员、如今的大厨，托拜厄斯刚经历离婚。一场意外的车祸让两人相遇，从此相爱、同居，也为要不要孩子争吵过。\n\n阿尔穆特被诊断出卵巢癌，治疗后病情缓解，两人有了女儿埃拉。癌症复发时，她决定去参加博古斯世界烹饪大赛。影片打乱时间顺序，在相遇、生子与告别之间来回跳跃，拼出一段十年的爱情。",
   "bio": "约翰·克劳利是爱尔兰导演，舞台剧出身，代表作《布鲁克林》（获奥斯卡最佳影片提名）、《金翅雀》，也执导过多部伦敦西区与百老汇舞台剧。他擅长细腻的人物情感与表演调度。",
   "st": "剧本由英国剧作家尼克·佩恩创作，用非线性的叙事把同一段关系的不同时间点交错剪在一起，让观众像记忆一样跳着经历这十年。影片于 2024 年多伦多国际电影节世界首映，并作为第 72 届圣塞巴斯蒂安国际电影节的闭幕片（非竞赛）放映。",
