   "syn": "曾经饱受抑郁困扰的演员李欣冉，在一场还俗派对上认识了刚刚还俗的朴原博。两人相恋、结婚，有了第一个孩子，带着几百万积蓄开始新生活。\n\n缺乏经验和大手大脚让积蓄一点点缩水。朴原博把全部希望押在安吉山里的一家手碟乐器工厂上，可第二个孩子出生、合伙人离开、债务越滚越大。争吵与和好轮番上演，两个人在泥沼里学着放下对完美生活的想象。",
   "bio": "秦潇越是中国纪录片导演、编剧。她的前作《巢》记录一个家庭的分合，获 FIRST 青年电影展最佳纪录长片。她习惯长时间跟拍普通家庭，关注亲密关系里的力量与脆弱。",
   "st": "影片以长期跟拍的方式记录这对夫妻，导演也参与摄影，称这是「一次极度疲惫又极度刺激的拍摄之旅」。主创不美化婚姻，也不评判谁对谁错，而是让观众看到两个人如何一起挣扎、一起妥协。影片入围 2025 年 FIRST 青年电影展主竞赛。",
