   "bio": "路易斯·克里希是法国动画导演，曾参与高卢英雄系列动画长片的导演工作。《钢铁男孩》把重心转向乡村成长、身体限制与音乐带来的可能。",
   "st": "这是一部将残障经验放入乡村日常的动画长片。故事没有停留在克服障碍的单一目标，而是让主人公学习重新理解劳动、家庭与自己的价值。",
