   "bio": "林乐骞执导本片，杨乐文、谈善言和邵美琪出演。故事借一桩悬案连接人物，将调查和各自隐藏的创伤交织，让类型悬念与日常关系共同推进。",
   "st": "影片以悬案为叙事入口，关注事件在不同人物生命中留下的痕迹。观看时可以把人物关系与信息出现的先后顺序放在一起，辨认真相被遮蔽的方式。",
