   "syn": "摄影师丽莎突然失踪。最后的线索指向她拍摄过的七个足球场——它们散落在格鲁吉亚七个偏远村庄。父亲伊拉克利踏遍这些球场寻女，丽莎的挚友、如幽灵般的列瓦尼悄然加入搜寻。每当球场更迭，相遇的村民与他们的故事便如走马灯般轮转。看似荒诞的旅程里暗涌渐起：每踏过一片坑洼的草场，每穿过一座寂静村庄，找到丽莎的希望便如晨雾般日渐稀薄。",
