   "syn": "影片以1962年的慕尼黑为背景，讲述了12岁的卡拉的真实故事。她对自己的父亲提起诉讼，寻求保护以免受其多年虐待。在艰难地走过司法程序的过程中，她与拉米法官之间建立了一种特殊的情感纽带——后者成为了她希望的灯塔。卡拉不愿完全吐露自己所受的痛苦，这逐渐迫使拉米法官给予她以自己的方式讲述故事的自由——而这一选择也将他自己的职业生涯置于风险之中。",
