   "syn": "「泥娃娃，泥娃娃，一个泥娃娃……。」午夜时分，当童谣幽幽响起，游戏企画旭川与怀孕的文物修护师妻子慕华的生活却早已变了调。那尊来自凶宅的泥娃娃暗中牵引怪事频发，唯能请讬通灵驱魔人阿生相助，不料泥娃娃背后的秘密更叫人毛骨悚然。《缉魂》金马最佳剪辑解孟儒首执导筒，取材同名儿歌，融合虚拟实境，并巧以空间营造极致恐怖，杨佑宁、蔡思韵、张轩睿合演附身惊悚。",
