   "dir": "李立劭",
   "dirO": "LEE Li-shao",
   "syn": "一记白恐枪响夺走父亲，李哲洋的命运骤然变调，自此遭情治紧盯，强制退学、留学受阻、乐途崎岖。但他自学成才，学院无路，山林起步，成为原民歌谣采集先驱，又藉编刊、翻译与著述，为乐迷引介世界音乐。他为岛国留声开窗，名字却隐没史册。《独舞者的乐章》导演李立劭为父立传，使其贡献重见天日，更重访当年采声现场，搜罗跨代回响，让孤行一生的独奏者，终获迟来伴奏。",
