   "dir": "黄肇邦",
   "dirO": "WONG Siu-pong",
   "syn": "窗外阳光高挂，屋内生命倒数。三名年轻女子罹患罕见脑癌，高价实验药成了病患与家属的仅存生机。以药为引，让孤注希望与沉重负荷随之流转，编成三段交会又分岔的抗病历程。冷色近拍共感愁容，幽暗斗室囚禁倦影，不催泪、不造梦，静守照护日常。面对挥之不去的死亡阴霾，信念在机率里摇晃，爱在失去前发亮。纵然暖意难握、韶光难留，依然照见求生代价、托住相伴重量。",
