   "dir": "姜雯洁",
   "dirO": "JIANG Wenjie",
   "syn": "当家不恢原貌，何以自处？韩丽珠与家猫白果共居，在搬迁间寻归处；李维怡驻守深水埗小店，把来往过客结成街坊；叶晓文入住山野，向草木鸟兽学栖居。许鞍华、文念中监制，延续《诗》的本土关怀，随三位作家穿城入村，记下笔耕、维生、安身。她们以文字筑巢，在香港变幻时如树生根，由失所、结群与生态，扩写归属边界。家非座标，亦非终点，于离散间重组、相遇里生成，总在到达中。",
