   "syn": "父亲在他幼时赴中国工作、另筑新家，长期缺席留下难填空白；母亲独力扶养子女，求好心切反令亲情紧绷。二十多年后，他持摄影机来回母亲与姊姊的家，欲补家庭裂缝，未料父亲重病返台，往日伏流再起漩涡。拍家人好难，太近难看明、太亲难说清。《度日》导演林佑恩长片首作，家似一座山，众人各自绕行，各守风景，难有交集。纵使未能一跃翻山，仍愿执镜入山，在迂回中走近彼此。",
