   "dirO": "SUN Xun",
   "syn": "煤炭帝国「螺刹」即将迎来六十年一度的迷梦节。举国欢腾筹备，殊不知暗地里有使人民失去记忆的帝国阴谋。手握「魔法星图」的魔术师乘飞艇周游至此，却遭逮捕入狱，进而邂逅孤儿小之。在迷梦节的狂乱中，魔术师将地图交予小之，改变了他的命运……。费时十年，集合木刻板画及山水墨等复合媒材，汇聚历史经典的绘画、壁画与书法，宛如人类艺术史大爆炸，交织成奇幻寓言。",
