   "syn": "网红玛莉亚公主与男友经营都市传说频道，但因一次取材失败，人气暴跌。此时，制偶大师朵莉夫人要为娃娃举办「回家派对」；玛莉亚因持有娃娃而受邀，两人视此为事业翻身的机会，要一起挖掘宅邸的秘密。然而，越是深入宅邸，怪事却接二连三发生；与此同时，朵莉夫人似乎也在幕后操控一切……。结合真人转描与2D手绘动画技术，绚丽与黑暗并存，探寻自我与爱的真相。",
