     "syn": "身为家庭厨师的赖姐，靠双脚与公车穿梭家户厨房，煮出各家口味菜肴之余，也陪著一起东家长西家短。但回到家里，与老公之间的隔阂却难以化解。当她偷偷报名驾训班，手握方向盘，才彷佛掌握了人生。婚姻天天如爬坡，总要留口气喘息。李宜珊监制，杨丽音、夏靖庭再续欢喜冤家。",
