     "min": 9,
     "dir": "林奕伶",
     "dirO": "LIN Yi-ling",
     "syn": "新闻传出女大学生坠楼事件，牙包的朋友留下一句「我要去冒险了」，再也不回来。牙包难以止歇的愤怒与埋怨，实则是回忆、遗憾、无法接受与替朋友松口气。一次意料之外的梦里相见，牙包终于有机会将千言万语倾吐而出。以2D动画呈现人物与空间变形，赭红、橄榄绿等暖色调为感伤垫底，温柔接住生者的哀伤。",
