     "dirO": "Fish WANG / YANG Ya-ting",
     "syn": "一场大地震让母子分离，母亲因故遗忘爱子，困囿于记忆中模糊缠绕的黑影。沉于地底的孩子，在无数黑夜里，向睡魔与黑狗诉说对妈妈的思念。碎纸传情，旋律指引，透过睡魔施法，孩子的心愿能否成真？金马奖得主王登钰合导新作，邀请雷光夏配乐，以幽暗奇幻编织爱的童话。",
