   "reg": "cn",
   "dir": "虞戡平",
   "dirO": "YU Kan-ping",
   "syn": "高中生阿青被发现与同性教职员私通而遭退学，颜面尽失的老兵父亲把他扫地出门，他只好前往台北新公园寻找一席之地。在杨师傅收容下，他结交一帮同志知己，邂逅同遭放逐的龙子，但过往的不堪童年记忆和家族阴影，却让他陷入无尽遗憾。改编白先勇代表作，4K数位修复经典再现，挑战戒严时期保守社会，邀请苏芮再度献唱，金马影帝孙越更开金嗓，为疼痛压抑的青春唱出最无畏禁忌的旋律。",
