     "dirO": "Nic HO",
     "syn": "升学主义挂帅，老旦校长挥舞偃月刀，强迫学生听话追高分。当姜思与小美出言顶撞，反抗的不仅是升学，还是规训的思想。惨遭校方点名追捕的他们患难生情谊，但谁能逃出当代血滴子的制裁？《铁臂猫黑别》导演新作，改编漫画家杨学德同名作品，侠义与赛博混搭，谈校园纯爱与自由。",
