     "syn": "乡间少年马进存了半年零钱，趁父母外出农忙时，与班长一同进城，要为母亲买一份生日礼物。从务实的保温瓶，到班长建议的女鞋与丝巾，再到有牌又实用的包包，马进始终没找到合意的礼物。直到一车鲜花经过，马进真挚浪漫的心突然涌现，这将会是他送给母亲的礼物吗？",
