   "dirO": "Olivier ASSAYAS",
   "syn": "苏联解体后，旧秩序崩塌、新资本崛起。青年瓦汀乘著时代巨浪，从剧场文青跃身电视圈鬼才，最终被招揽进入权力核心，以高超的舆论操弄手腕，助政坛新秀普丁登上总理宝座，打造新一代强人神话。他见证俄罗斯的华丽蜕变，却也在谎言与野心中迷失自我，一步步成为独裁体制、侵略战争的帮凶。深陷权力漩涡的他，能否从凶险的斗争中全身而退？",
