   "syn": "父亲夸口说他能创造出这世界上任何的果酱，男孩也曾如此坚信不移。在纽泽西州，身上流著高加索切尔克斯裔血统，意味著永远得在弱肉强食中力争上游，男孩在摔角场上奋力翻滚，也在场下为父亲的未来奔走烦忧。颓丧失意的父亲、即将临盆的姑姑，以及性情不定的父亲友人，拼凑出自家餐馆的萎靡一隅；而那个藏著秘密的摔角女孩，吸引了男孩的注意，但悲剧总是猝不及防地降临。",
