   "syn": "德高望重的小镇医生在妻子过世后独自抚养儿子，早已功成名就的他，满心期盼软弱的儿子能像自己一样优秀。当一具罗姆人的尸体被送往医院等候警方调查，醒目的黄色脚踏车成了被指控杀人的铁证。随著儿子不为人知的一面曝光，他完美无瑕的世界与仅存的盼望，也随之瓦解。",
