   "dirO": "Mohsen GHARAEI",
   "syn": "家园即将拆除进行都更重建，从事狱警工作几十年的老父被指控收贿，停职期间，他意外得知大女儿为了模特儿梦早已买好机票要闯荡世界，连妻小都默许把欺骗当成彼此共业。内忧外患搞得他心烦意乱理智断线，竟把监狱生活原封不动搬回家当作考验。房屋拆迁迫在咫尺，他不顾一切想要阻止，当爱变质成无止尽的控制，摇摇欲坠的是房子，还是记忆中家的样子？",
