   "syn": "冲绳的湛蓝天空与蔚蓝海面连成一线，军机划过天际的低沉轰鸣，居民早已习以为常。高中最后一个暑假，忧郁的龟生与朋友们成日在海边悠游晃荡，随心思索著逃离岛屿的未来；住在美军基地的金发少年柯林闯入他们的世界，却只想留在岛上独享一方天地。随著当地居民与驻军关系日益紧张，两人既矛盾又相似的微妙关系，令龟生深埋心中的不安全感蠢蠢欲动。",
