   "syn": "仰光的成衣厂里，年轻的珊姬为了勉强维持生计，弯腰埋首缝纫机前，在遭主管责难时，遇见了替她解围的温柔新同事婷婷。两人在日复一日的乏味工作间偷得片刻闲暇，或在夜里并肩同睡一张床榻，珊姬的情感如芒果树般无声滋长，悄然结出满树果实，甚至暗自盘算带著婷婷一起回到梦想中的北方家园，共筑生活。然而，婷婷突然神秘失联，让一切都乱了套……。",
