   "syn": "高级俱乐部，蓝粉亮制服，初来乍到的少女忙里偷闲，兜转在明媚高尔夫球场间，满怀期待寻觅心仪老板，渴望能一飞冲天。有钱叔叔带侄女体验阶级飨宴，球场清一色女职员，排排站蹲胯间，球放前面腿站两边，嘻笑打屁回以笑颜。酷暑干旱在这里无须操烦，源源不绝土芒果什么都能解决，不论服侍哪一颗球，欢迎光临美丽新世界。制服一穿，人人都是菲律宾女孩。",
