   "dirO": "George JAQUES",
   "syn": "最讨厌被贴上癌症病人标签的少女艾薇，像刺猬般拒绝所有关心，父母却偏偏替她报名为期一个月的病友夏令营，以为可以让她重拾生活热情。在这个人人以病历当开场白、热情得令人招架不住的营队里，艾薇对规范和团康一概嗤之以鼻，直到遇见一群同样不想乖乖当「病人」的叛逆伙伴。他们闯祸、冒险、谈恋爱，把营队搞得天翻地复，也在彼此身上找到一个不必坚强、无须解释自己的地方。",
