   "dirO": "Garth JENNINGS",
   "syn": "今晚的演出是一场安可，安可表示你想要更多，现在开始尖叫拍手，好戏马上就要开播！事隔24年的漫长等候，英摇代表Pulp终于回锅，带著新专辑升起舞台霓虹闪烁，随节奏四肢扭动跳迪斯可，低沉气泡音开启时空穿梭。儿时看电视幻想太空生活，乐团成员不断来了又走，救济金信封写满歌词创作，沉寂多年终于迎来成果，登上巅峰后面对坠落，现实人生已改变太多，未来又该往哪里走？",
