   "dirO": "Chandler LEVACK",
   "syn": "列出今年夏天的待办清单，乐评葛蕾丝凭著一股毅然决然，裸辞离乡到蒙特娄发展。写一本书谈场恋爱登一座山，目标说得容易起头难。参加朋友派对那一晚，她的命运竟就此转弯，和禁欲贝斯手彻夜相谈甚欢，被混蛋主唱迷得芳心大乱，甚至一口答应帮乐团宣传。追爱路上磕磕绊绊，追求理想进度中断，眼看爱情友情事业通通都要完蛋，她该怎么重整人生的一团混乱？",
