   "syn": "为了修复破碎亲情，富商菲利普邀请爱女玛德莲一同游巴黎，女儿却只想看电脑萤幕里的宅宅科学家与鱼头丑恐龙魔法对轰。顾人怨老爸碎嘴念不停，玛德莲忍无可忍暴饮暴食应喙应舌，战况升级引来爱管闲事的服务生露西，以预防家暴为名勾勾缠。眼见与女儿的相处时光彻底被毁，菲利普气噗噗跑回房间耍自闭，才发现冤家父女没有心连心只剩肚连肚，失控场面一触即发。",
