   "syn": "天才数学家麦克斯执著定理，深信万物都能以数字解密，孤寡一人独居公寓，头痛妄想如影随形。一日发现216位数能破解宇宙运行，引来各路人马争相追缉，让他沉溺谜题却又身陷危机……。戴伦艾洛诺夫斯基一鸣惊人首作，黑白反差脑内震动，电子节拍狂乱惊悚，直探恐惧心灵角落。",
